-- 25 September 2026 daily current-affairs desk.
-- Original student-facing briefs verified against the linked official sources.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
  $$2026-09-25-edible-oil-basic-customs-duty-reduction$$, $$2026-09-25$$,
  $$Government cuts basic customs duty on key imported edible oils$$,
  $$The Centre reduced basic customs duty on crude sunflower oil from 10% to zero and on crude soybean and crude palm oils from 10% to 5%. It also reduced the applicable duty on their refined forms while retaining a 19.25% duty gap between crude and refined edible oils.$$,
  $$This is a direct link between customs policy, imported inflation and domestic processing. In an exam, separate Basic Customs Duty from the final retail price: the duty change affects landed cost, while passing the benefit to consumers depends on the supply chain.$$,
  $$Edible-oil imports contribute to domestic availability and prices. A larger duty difference between crude and refined imports can make domestic refining comparatively more attractive, because crude oil can be imported and processed within India. The release says industry was asked to revise distributor and maximum retail prices to reflect lower landed costs.$$,
  $$Government Cuts Import Duty on Major Edible Oils to Provide Relief to Consumers$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2314297&lang=1&reg=3$$,
  $$Ministry of Consumer Affairs, Food and Public Distribution / Press Information Bureau$$, $$2026-09-24$$,
  $$["Basic Customs Duty on crude sunflower oil was cut from 10% to nil.","Basic Customs Duty on crude soybean oil and crude palm oil was cut from 10% to 5%.","The release says a 19.25% duty differential between crude and refined edible oils was retained.","Import duty affects an import's landed cost and can influence domestic food-price inflation."]$$::jsonb,
  $$[{"question":"Which crude edible oil received a nil Basic Customs Duty in this decision?","answer":"Crude sunflower oil."},{"question":"Why can a duty gap between crude and refined oil matter?","answer":"It can support domestic refining by making imported crude oil relatively more attractive for processing in India."}]$$::jsonb,
  $${"title":"From border duty to food prices","steps":["A customs-duty change alters an imported oil's landed cost.","Importers and refiners adjust procurement and processing decisions.","The supply chain can revise distributor and retail prices.","Lower import costs may help ease edible-oil and wider food-price pressures."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-25-fssai-draft-paneer-labelling-rule$$, $$2026-09-25$$,
  $$FSSAI proposes to reserve the name ‘paneer’ for milk-derived products$$,
  $$FSSAI issued a draft amendment that would prevent products made from non-milk constituents from being labelled or marketed as paneer. The proposal is open to objections and suggestions before it can become a final rule.$$,
  $$This is a food-regulation and consumer-protection item. The important distinction is legal status: a draft regulation signals a proposed change; it does not yet create a final, enforceable amendment.$$,
  $$The proposal would add a clause dealing with paneer made from constituents not derived from milk to the Food Safety and Standards (Prohibition and Restrictions on Sales) Regulations, 2011. Products licensed or registered as ‘Analogue in Dairy Context’ would have to stop using ‘paneer’ in their nomenclature, label or marketing if the draft is finalised.$$,
  $$FSSAI proposes draft amendment to ensure only milk-derived products are represented as ‘Paneer’$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2314542&lang=2&reg=48&v=2$$,
  $$Food Safety and Standards Authority of India / Press Information Bureau$$, $$2026-09-24$$,
  $$["The proposal is a draft amendment, not a final regulation.","It concerns the Food Safety and Standards (Prohibition and Restrictions on Sales) Regulations, 2011.","The draft targets use of ‘paneer’ for products whose constituents are not derived from milk.","FSSAI invited public objections and suggestions for 60 days from availability of the Gazette notification."]$$::jsonb,
  $$[{"question":"Has the paneer-labelling change already become final law?","answer":"No. FSSAI described it as a draft amendment and invited objections and suggestions."},{"question":"Which regulator issued the proposal?","answer":"The Food Safety and Standards Authority of India (FSSAI)."}]$$::jsonb,
  $${"title":"How a draft food rule becomes operative","steps":["The regulator publishes a draft amendment.","Stakeholders may submit objections and suggestions.","The regulator considers the responses and finalises the text if it proceeds.","A final notified rule then sets the enforceable labelling requirement."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-25-national-formulary-biovigilance-programme$$, $$2026-09-25$$,
  $$India launches National Formulary of India 2026 and approves a Biovigilance Programme$$,
  $$The Indian Pharmacopoeia Commission launched the seventh National Formulary of India, a hospital guidance document for medical-device adverse-event reporting and the ADR-PvPI 2.0 iOS app. The Government also approved the Biovigilance Programme of India for monitoring adverse events linked to organ and tissue transplantation.$$,
  $$This combines pharmaceutical standards with post-market patient safety. It is useful for questions that distinguish pharmacovigilance, which tracks adverse drug reactions, from biovigilance, which covers biological materials such as organs and tissues.$$,
  $$The National Formulary of India supports rational prescribing and use of medicines. The release identifies the Indian Pharmacopoeia Commission as the body that will lead the new Biovigilance Programme. It also reports roughly 1,150 adverse-drug-reaction reporting centres and a plan to extend the network towards primary-healthcare level.$$,
  $$Union MoS for Health launches 7th National Formulary of India 2026 and announces Biovigilance Programme$$,
  $$https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2312930&lang=2&reg=48$$,
  $$Ministry of Health and Family Welfare / Indian Pharmacopoeia Commission / Press Information Bureau$$, $$2026-09-21$$,
  $$["The 2026 edition is the seventh National Formulary of India.","The Government approved the Biovigilance Programme of India for adverse events involving organ and tissue transplantation.","The Indian Pharmacopoeia Commission is to lead the Biovigilance Programme.","The release links the NFI to evidence-based and rational prescribing."]$$::jsonb,
  $$[{"question":"Which institution will lead India's Biovigilance Programme according to the release?","answer":"The Indian Pharmacopoeia Commission (IPC)."},{"question":"What is the NFI chiefly meant to support?","answer":"Evidence-based, rational prescribing and use of medicines."}]$$::jsonb,
  $${"title":"Patient-safety information loop","steps":["A medicine, device, organ or tissue is used in care.","A suspected adverse event is reported through the relevant safety system.","The regulator and technical institution analyse patterns and risks.","Guidance, monitoring and safer clinical practice are strengthened."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-25-mca-nidhi-company-investor-advisory$$, $$2026-09-25$$,
  $$MCA cautions investors about non-compliant Nidhi companies and uninsured deposits$$,
  $$The Ministry of Corporate Affairs advised the public to verify Nidhi companies before investing, especially where high returns are promised. It reiterated the NDH-4 requirement and noted that deposits with Nidhi companies are not covered by DICGC insurance.$$,
  $$This is a financial-awareness and corporate-regulation topic. It tests the difference between a Nidhi company and a bank, and the scope of deposit insurance rather than treating every entity that accepts member deposits as a regulated bank.$$,
  $$A company wishing to operate as a Nidhi must apply through Form NDH-4 to be declared or updated as a Nidhi. The release says only 395 companies had been declared as Nidhis to date and warns that many firms using the Nidhi label had not completed the required compliance process.$$,
  $$MCA issues advisory - cautions public against high-return promises by non-compliant Nidhi Companies$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2314436&lang=1&reg=3$$,
  $$Ministry of Corporate Affairs / Press Information Bureau$$, $$2026-09-24$$,
  $$["A company seeking to function as a Nidhi must file Form NDH-4.","The Ministry cautioned against investment decisions based on high-return promises without verification.","The release says deposits in Nidhi companies are not insured by DICGC.","Nidhi companies are governed by company-law rules and are not the same as commercial banks."]$$::jsonb,
  $$[{"question":"Are deposits in Nidhi companies insured by DICGC?","answer":"No, the MCA advisory explicitly says they are not."},{"question":"Which form is required for a company to be declared or updated as a Nidhi?","answer":"Form NDH-4."}]$$::jsonb,
  $${"title":"Checking a Nidhi before investing","steps":["A company seeks Nidhi status through the prescribed filing.","MCA examines the required compliance information.","Investors should verify the entity's status rather than rely on return promises.","Nidhi deposits remain outside DICGC deposit insurance."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-25-galaxeye-optosar-rdi-support$$, $$2026-09-25$$,
  $$TDB supports GalaxEye’s indigenous OptoSAR Earth-observation satellite project$$,
  $$The Technology Development Board signed an agreement to provide ₹63.84 crore from the Research, Development and Innovation Fund to GalaxEye Space Solutions. The project seeks to develop a high-resolution multisensor satellite that combines synthetic-aperture radar and optical imaging.$$,
  $$This is an example of public support for private-sector deep technology. It connects Earth observation, technology-readiness levels and the difference between a research-development grant or support agreement and a satellite already in orbit.$$,
  $$The release gives the total approved project cost as ₹247.69 crore. It says the OptoSAR system is intended to deliver sub-0.5-metre imaging and mature from Technology Readiness Level 6 to TRL 9. SAR can capture imagery in conditions where ordinary optical imaging may be constrained by cloud cover or darkness.$$,
  $$TDB-DST signs agreement with GalaxEye for ₹63.84 crore RDI support to develop next-generation multisensor satellite technology$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2314385&lang=1&reg=3$$,
  $$Technology Development Board, Department of Science and Technology / Press Information Bureau$$, $$2026-09-24$$,
  $$["TDB agreed ₹63.84 crore of RDI support for the project.","The total approved project cost is ₹247.69 crore.","OptoSAR combines synthetic-aperture radar and optical imaging.","The stated development path is from TRL 6 to TRL 9."]$$::jsonb,
  $$[{"question":"What two sensing modes does OptoSAR combine?","answer":"Synthetic-aperture radar (SAR) and optical imaging."},{"question":"Does TRL 6 to TRL 9 mean the satellite is already operational in orbit?","answer":"No. It describes technology maturation, validation and readiness towards deployment."}]$$::jsonb,
  $${"title":"Maturing a multisensor satellite technology","steps":["An advanced prototype combines radar and optical sensing.","RDI support funds engineering, validation and scale-up.","The technology advances through higher readiness levels.","A deployable Earth-observation capability can follow successful maturation."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-25-bioe3-biodegradable-plastic-commercialisation$$, $$2026-09-25$$,
  $$BioE3-linked pilot advances bio-based biodegradable plastic towards commercial use$$,
  $$The Department of Biotechnology formally launched commercial use of a bio-based biodegradable plastic based on polylactic acid (PLA), with Balrampur Chini Mills taking the initiative forward under the BioE3 framework. A ₹75 crore BIRAC grant supports a 100-tonnes-per-annum pilot-scale research and development facility for PLA and co-polymers.$$,
  $$This is a biomanufacturing and circular-economy development. PLA is a polymer made from biological feedstocks; a pilot facility and commercial launch should not be confused with a nationwide ban on conventional plastic or proof that all ‘biodegradable’ products degrade in every environment.$$,
  $$BioE3 stands for Biotechnology for Economy, Environment and Employment. The reported facility is to be established at the company’s Kumbhi manufacturing complex in Uttar Pradesh, with the stated aim of scaling bio-based material technologies from development toward commercial production.$$,
  $$Commercial launch of Bio-based Biodegradable Plastic under BioE3$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2314491&lang=1&reg=3$$,
  $$Department of Biotechnology, Ministry of Science and Technology / Press Information Bureau$$, $$2026-09-24$$,
  $$["PLA means polylactic acid, a bio-based polymer used for biodegradable-plastic applications.","The activity is linked to BioE3: Biotechnology for Economy, Environment and Employment.","BIRAC support described in the release is ₹75 crore for a 100-TPA pilot-scale PLA and co-polymer facility.","The facility is planned at Kumbhi in Uttar Pradesh."]$$::jsonb,
  $$[{"question":"What does PLA stand for in this bio-based plastic development?","answer":"Polylactic acid."},{"question":"What does BioE3 expand to?","answer":"Biotechnology for Economy, Environment and Employment."}]$$::jsonb,
  $${"title":"From biomass to bio-based material","steps":["Biological feedstocks are converted into polymer-building materials.","A pilot facility develops and validates PLA and co-polymer processes.","Industrial partners scale the technology toward commercial production.","Bio-based materials can create circular-economy value chains when used and managed appropriately."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-25-iitgn-taiwan-semiconductor-research-partnerships$$, $$2026-09-25$$,
  $$IIT Gandhinagar signs semiconductor-research partnerships with three Taiwanese universities$$,
  $$IIT Gandhinagar signed memoranda of understanding with Taipei Tech, Taiwan Tech and National Central University during a Taiwan visit. The agreements cover research, academic exchange and talent development in semiconductors, artificial intelligence and related emerging technologies.$$,
  $$This is a science-diplomacy and semiconductor-capacity item. It is useful for understanding how universities, research hubs and international collaboration contribute to a semiconductor ecosystem; the MoUs do not themselves create a semiconductor fabrication plant.$$,
  $$The official release identifies IITGN’s Silicon and Advanced Semiconductor Manufacturing Research and Training Hub, SAMARTH, as a workforce-development, applied-research and industry-collaboration platform. The three partner institutions are National Taipei University of Technology, National Taiwan University of Science and Technology and National Central University.$$,
  $$IIT Gandhinagar Partners with Three Taiwanese Universities to Advance Semiconductor and Emerging Technology Research$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2314416&lang=2&reg=48$$,
  $$Ministry of Education / IIT Gandhinagar / Press Information Bureau$$, $$2026-09-24$$,
  $$["IIT Gandhinagar signed MoUs with Taipei Tech, Taiwan Tech and National Central University.","The areas include semiconductors, AI, research collaboration and talent development.","SAMARTH at IITGN focuses on semiconductor workforce development, applied research and industry collaboration.","The partnerships were concluded during an IITGN delegation visit to Taiwan from 20 to 25 September 2026."]$$::jsonb,
  $$[{"question":"Name any one of IITGN's three Taiwanese MoU partners in this release.","answer":"Taipei Tech, Taiwan Tech or National Central University."},{"question":"What does SAMARTH at IIT Gandhinagar support?","answer":"Semiconductor workforce development, applied research, technology innovation and industry collaboration."}]$$::jsonb,
  $${"title":"Building semiconductor capability through collaboration","steps":["Universities connect specialised research and teaching strengths.","MoUs enable exchanges, joint research and knowledge sharing.","A domestic research-and-training hub links academia with industry needs.","The resulting talent and research base supports a wider semiconductor ecosystem."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-25-make-in-india-twelve-year-backgrounder$$, $$2026-09-25$$,
  $$PIB backgrounder reviews Make in India at 12 years$$,
  $$A PIB Research backgrounder marked 12 years of Make in India and updated key manufacturing indicators and policy context. It notes that Make in India 2.0 covers 27 sectors: 15 manufacturing and 12 services.$$,
  $$This is a revision-ready policy context brief for economy and industrial-policy questions. Use the backgrounder to identify the programme’s objective and related tools, but do not treat an anniversary review as a new manufacturing scheme or a single data-series release.$$,
  $$Make in India was launched on 25 September 2014 to strengthen investment, innovation and manufacturing. The backgrounder links the programme’s wider ecosystem to initiatives such as the National Single Window System, Production Linked Incentive schemes, PM GatiShakti and the India Industrial Land Bank. It reports manufacturing GVA at constant prices grew at a 10.88% CAGR between 2022-23 and 2025-26 under the revised national-accounts series.$$,
  $$12 Years of Make in India$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2314447&lang=1&reg=3$$,
  $$PIB Research, Press Information Bureau$$, $$2026-09-24$$,
  $$["Make in India was launched on 25 September 2014.","Make in India 2.0 focuses on 27 sectors: 15 manufacturing and 12 services.","The backgrounder links industrial policy with NSWS, PLI, PM GatiShakti and the India Industrial Land Bank.","It reports a 10.88% CAGR in manufacturing GVA at constant prices from 2022-23 to 2025-26 under the revised series."]$$::jsonb,
  $$[{"question":"When was Make in India launched?","answer":"25 September 2014."},{"question":"How many sectors are identified in Make in India 2.0 in the PIB backgrounder?","answer":"Twenty-seven: 15 manufacturing and 12 services sectors."}]$$::jsonb,
  $${"title":"Make in India policy ecosystem","steps":["Industrial policy seeks to attract investment and expand productive capacity.","Enabling platforms improve approvals, logistics and land information.","Sector-specific measures such as PLI encourage targeted manufacturing investment.","Output, value added, exports and jobs are tracked as industrial-development outcomes."]}$$::jsonb,
  $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title,
  summary = excluded.summary,
  why_it_matters = excluded.why_it_matters,
  background = excluded.background,
  source_title = excluded.source_title,
  source_url = excluded.source_url,
  source_publisher = excluded.source_publisher,
  source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways,
  quick_check = excluded.quick_check,
  visual_data = excluded.visual_data,
  status = excluded.status,
  reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id
from public.current_affairs_briefs briefs
cross join public.exams exams
where briefs.slug in (
  $$2026-09-25-edible-oil-basic-customs-duty-reduction$$,
  $$2026-09-25-fssai-draft-paneer-labelling-rule$$,
  $$2026-09-25-national-formulary-biovigilance-programme$$,
  $$2026-09-25-mca-nidhi-company-investor-advisory$$,
  $$2026-09-25-galaxeye-optosar-rdi-support$$,
  $$2026-09-25-bioe3-biodegradable-plastic-commercialisation$$,
  $$2026-09-25-iitgn-taiwan-semiconductor-research-partnerships$$,
  $$2026-09-25-make-in-india-twelve-year-backgrounder$$
)
and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
